def run(args, timeout=7200, cwd=None):
    p = subprocess.run(args, capture_output=True, text=True, timeout=timeout, cwd=cwd)
    if p.returncode != 0:
        raise SskError("ffmpeg ব্যর্থ: " + clean(p.stderr[-700:], 500))
    return p


def probe(path) -> dict:
    p = subprocess.run([FFPROBE, "-v", "error", "-print_format", "json", "-show_format",
                        "-show_streams", str(path)], capture_output=True, text=True, timeout=300)
    if p.returncode != 0:
        raise SskError("ffprobe ব্যর্থ: " + clean(p.stderr, 200))
    j = json.loads(p.stdout or "{}")
    v = next((s for s in j.get("streams", []) if s.get("codec_type") == "video"), {})
    a = next((s for s in j.get("streams", []) if s.get("codec_type") == "audio"), {})
    return {"duration": float(j.get("format", {}).get("duration") or 0),
            "size": int(j.get("format", {}).get("size") or 0),
            "width": int(v.get("width") or 0), "height": int(v.get("height") or 0),
            "has_audio": bool(a)}


def cookie_text(raw: str) -> str:
    """ইউজারের YT_COOKIES সিকারেট পরিষ্কার করে সঠিক Netscape ফাইল বানায়।

    আসল ভুল: সিকারেটের প্রথম লাইন ছিল 'Netscape HTTP Cookie File' — কিন্তু python-এর
    cookiejar '# Netscape HTTP Cookie File' (হ্যাশ সহ) চায়, নাহলে "does not look like
    a Netscape format cookies file" এরর দিয়ে কুকি লোড হয় না → ইউটিউব "Sign in to
    confirm you're not a bot" দেখায়।
    """
    rows = [ln for ln in str(raw or "").splitlines()
            if len(ln.split("\t")) == 7 and ln.split("\t")[0].strip()]
    return COOKIE_HEADER + "".join(ln if ln.endswith("\n") else ln + "\n" for ln in rows)


def write_cookies(raw: str, dest: Path) -> Path:
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(cookie_text(raw), encoding="utf-8")
    return dest


def font_file() -> str | None:
    for path in FONT_CANDIDATES:
        if os.path.exists(path):
            return path
    return None


# ------------------------------------------------------- channel sanitizing
def norm_channel_url(raw) -> str:
    """যেকোনো রকম লেখা থেকে সঠিক চ্যানেল লিংক বানায়; ভুল/খালি হলে '' ফেরত দেয়।

    @crimealert            -> https://youtube.com/@crimealert
    crimealert             -> https://youtube.com/@crimealert
    youtube.com/@x/        -> https://youtube.com/@x
    UCxxxxxxxxxxxxxxxxxxxx -> https://youtube.com/channel/UCxxxx...
    https://youtube.com/@   -> ''   (এই খালি হ্যান্ডেলটাই আগের বাগ ছিল)
    """
    s = str(raw or "").strip().replace("\u200b", "")
    s = re.sub(r"^[•\*\-\s]+", "", s).strip()
    if not s:
        return ""
    if s.startswith("@"):
        handle = s[1:].strip()
        return "https://youtube.com/@" + handle if re.fullmatch(r"[A-Za-z0-9_.\-]{3,}", handle) else ""
    if re.match(r"^(https?://)?(www\.)?(m\.)?youtube\.com/", s, re.I) or \
       re.match(r"^(https?://)?youtu\.be/", s, re.I):
        u = s if s.lower().startswith("http") else "https://" + s
        u = re.sub(r"^http://", "https://", u, flags=re.I)
        u = u.split("?")[0].rstrip("/")
        u = re.sub(r"^https://(www\.|m\.)?youtube\.com", "https://youtube.com", u, flags=re.I)
        rest = u.split("youtube.com/", 1)[-1] if "youtube.com/" in u else u
        if not rest or rest in ("@", "c", "channel", "user"):
            return ""
        if rest.startswith("@"):
            return u if re.fullmatch(r"[A-Za-z0-9_.\-]{3,}", rest[1:]) else ""
        return u
    if re.fullmatch(r"UC[A-Za-z0-9_\-]{20,}", s):
        return "https://youtube.com/channel/" + s
    if re.fullmatch(r"[A-Za-z0-9_.\-]{3,}", s):
        return "https://youtube.com/@" + s
    return ""


def clean_channels(cfg: dict, platform: str) -> list:
    """config থেকে বৈধ চ্যানেলের তালিকা (ক্রম ঠিক রেখে, ডুপ্লিকেট ও খালি বাদ)।"""
    out = []
    for raw in (cfg.get(f"{platform}_channels") or []):
        c = norm_channel_url(raw)
        if c and c not in out:
            out.append(c)
    return out


def channel_for_slot(cfg: dict, platform: str, slot: int) -> str:
    """প্রতিটি স্লটের নিজের চ্যানেল: স্লট ০ → প্রথম, স্লট ১ → দ্বিতীয়, ..."""
    chans = clean_channels(cfg, platform)
    if not chans:
        raise SskError(f"{platform}-এর কোনো বৈধ চ্যানেল সেট করা নেই "
                       "(ড্যাশবোর্ডের চ্যানেল কার্ডে স্লটগুলো ভরো)")
    return chans[slot % len(chans)]


# ------------------------------------------------------------------ yt-dlp
# --------------------------------------------------------------- yt-dlp নিরাপদ ইমপোর্ট
def ensure_ytdlp():
    """yt-dlp ইনস্টল না থাকলে নিজে ইনস্টল করে ইমপোর্ট করে দেয় (Actions-এ মডিউল মিসিং এরর বন্ধ)।"""
    try:
        import yt_dlp
        return yt_dlp
    except ImportError:
        pass
    for extra in ([], ["--user"]):
        try:
            subprocess.run([sys.executable, "-m", "pip", "install", "--quiet", "--upgrade", "yt-dlp"] + extra,
                           capture_output=True, text=True, timeout=900)
        except Exception:
            continue
        try:
            import importlib
            import yt_dlp
            importlib.reload(yt_dlp)
            return yt_dlp
        except ImportError:
            continue
    raise SskError("yt-dlp ইনস্টল করা গেল না — workflow-এর pip ধাপ দেখো")


# ---------------------------------------------------------- YouTube Data API (fallback)
YT_API = "https://www.googleapis.com/youtube/v3"


def _api_key() -> str:
    return env("YOUTUBE_API_KEY") or env("YT_API_KEY")


def _api(path: str, params: dict) -> dict:
    key = _api_key()
    if not key:
        raise SskError("YOUTUBE_API_KEY নেই — তালিকা বের করা যাবে না")
    q = dict(params)
    q["key"] = key
    r = requests.get(f"{YT_API}/{path}", params=q, timeout=60)
    if r.status_code != 200:
        raise SskError(f"YouTube API {path} {r.status_code}: {clean(r.text, 200)}")
    return r.json()


def iso_seconds(text) -> float:
    m = re.match(r"P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+(?:\.\d+)?)S)?", str(text or ""))
    if not m:
        return 0.0
    d, h, mi, s = (float(x) if x else 0.0 for x in m.groups())
    return d * 86400 + h * 3600 + mi * 60 + s


def stamp_epoch(text):
    if not text:
        return None
    try:
        from datetime import datetime
        return datetime.fromisoformat(str(text).replace("Z", "+00:00")).timestamp()
    except Exception:
        return None


def handle_of(url):
    """channel লিংক থেকে (kind, value) — kind: id | handle | search"""
    u = str(url or "").strip().rstrip("/")
    if "/channel/" in u:
        return "id", u.split("/channel/")[-1].split("/")[0]
    if "/@" in u:
        return "handle", u.split("/@")[-1].split("/")[0]
    if u.startswith("@"):
        return "handle", u[1:].split("/")[0]
    if re.fullmatch(r"UC[\w-]{20,}", u):
        return "id", u
    return "search", (u.split("/")[-1] or u)


def api_channel_entries(url, limit: int = 15) -> list:
    """YouTube Data API দিয়ে চ্যানেলের সর্বশেষ ভিডিও (duration + তারিখ সহ) — কুকি লাগে না।"""
    kind, value = handle_of(url)
    info = {}
    if kind == "id":
        info = _api("channels", {"part": "contentDetails,snippet", "id": value})
    else:
        if kind == "handle":
            info = _api("channels", {"part": "contentDetails,snippet", "forHandle": value})
        if not info.get("items"):
            info = _api("channels", {"part": "contentDetails,snippet", "forUsername": value})
        if not info.get("items"):
            s = _api("search", {"part": "snippet", "type": "channel", "maxResults": 1, "q": value})
            cid = ((s.get("items") or [{}])[0].get("id", {}) or {}).get("channelId")
            info = _api("channels", {"part": "contentDetails,snippet", "id": cid}) if cid else {}
    if not info.get("items"):
        return []
    item = info["items"][0]
    uploads = ((item.get("contentDetails") or {}).get("relatedPlaylists") or {}).get("uploads")
    if not uploads:
        return []
    want = max(1, min(400, int(limit)))
    ids, stamps, token = [], {}, None
    while len(ids) < want:
        params = {"part": "contentDetails,snippet", "playlistId": uploads, "maxResults": 50}
        if token:
            params["pageToken"] = token
        pl = _api("playlistItems", params)
        for it in pl.get("items") or []:
            cd = it.get("contentDetails") or {}
            vid = cd.get("videoId") or ((it.get("snippet") or {}).get("resourceId") or {}).get("videoId")
            if not vid or vid in stamps:
                continue
            ids.append(vid)
            stamps[vid] = (it.get("snippet") or {}).get("publishedAt")
        token = pl.get("nextPageToken")
        if not token:
            break
    if not ids:
        return []
    out = []
    for i in range(0, len(ids), 50):
        vr = _api("videos", {"part": "snippet,contentDetails,statistics",
                             "id": ",".join(ids[i:i + 50])})
        for v in vr.get("items") or []:
            sn, cd, st = v.get("snippet") or {}, v.get("contentDetails") or {}, v.get("statistics") or {}
            out.append({"id": v.get("id"), "title": sn.get("title") or "",
                        "duration": iso_seconds(cd.get("duration")),
                        "timestamp": stamp_epoch(sn.get("publishedAt") or stamps.get(v.get("id"))),
                        "view_count": int(st.get("viewCount") or 0),
                        "channel": sn.get("channelTitle") or value})
    return out


def scan_channel(url: str, limit: int = 15, cookies: str = "", deep: int = 0) -> list:
    """চ্যানেলের ভিডিও তালিকা — প্রথমে YouTube Data API (দ্রুত, কুকি লাগে না), না পেলে yt-dlp।

    আগে উল্টো ছিল: yt-dlp আগে চেষ্টা করত, আর ক্রেডেনশিয়াল পুরোনো হলে প্রতিটি চ্যানেলে
    মিনিটের পর মিনিট আটকে থাকত — এই দীর্ঘ অপেক্ষাই "preparing" হয়ে ঘণ্টা পার করে দিত।
    """
    target = str(url).split("?")[0].rstrip("/")
    if not target.endswith("/videos"):
        target += "/videos"
    entries = []
    try:
        entries = api_channel_entries(str(url), int(deep or max(int(limit), 150)))
        if entries:
            core.log(f"YouTube API দিয়ে তালিকা ({target}) — {len(entries)}টি")
    except Exception as exc:
        core.log(f"YouTube API তালিকা ব্যর্থ ({target}): {clean(exc, 160)}", "warn")
    if not entries:
        try:
            yt_dlp = ensure_ytdlp()
            opts = {"quiet": True, "no_warnings": True, "skip_download": True, "extract_flat": False,
                    "ignoreerrors": True, "playlistend": int(limit), "socket_timeout": 20,
                    "extractor_args": {"youtube": {"player_client": ["default", "web"]}}}
            if cookies:
                opts["cookiefile"] = str(write_cookies(cookies, Path(core.WORK) / "cookies.txt"))
            with yt_dlp.YoutubeDL(opts) as ydl:
                info = ydl.extract_info(target, download=False)
            entries = [e for e in ((info or {}).get("entries") or []) if e and e.get("id")]
        except Exception as exc:
            core.log(f"yt-dlp তালিকা ব্যর্থ ({target}): {clean(exc, 160)}", "warn")
            entries = []
    return entries


def pick_source(cfg: dict, platform: str, slot: int) -> dict:
    channels = clean_channels(cfg, platform)
    if not channels:
        raise SskError(f"{platform}-এর চ্যানেল সেট করা নেই")
    own = channel_for_slot(cfg, platform, slot)
    order = [own] + [c for c in channels if c != own]
    # ✅ আগের বাগ: এখানে history_sources(...) লেখা ছিল, কিন্তু সেটি core-এর ভেতরে —
    # তাই "name 'history_sources' is not defined" এররে ৬টি কাজই ব্যর্থ হচ্ছিল।
    used = core.history_sources(platform) | {j.get("source_id") for j in core.jobs().values()
                                             if j.get("platform") == platform}
    day = 0 if cfg.get("allow_any_age") else int(cfg.get("day_filter", 60))
    cap = float(cfg.get("max_duration_minutes", 80)) * 60
    floor = float(cfg.get("min_duration_seconds", 60))
    cookies = env("YT_COOKIES")
    notes, why, picks = [], {"young": 0, "long": 0, "short": 0, "nometa": 0, "used": 0}, []
    for channel in order:
        try:
            entries = scan_channel(channel, int(cfg.get("metadata_probe_limit", 15)), cookies,
                                  deep=int(cfg.get("api_scan_limit", 300)))
        except Exception as exc:
            notes.append(f"{channel}: {clean(exc, 120)}")
            continue
        if not entries:
            notes.append(f"{channel}: তালিকা খালি")
            continue
        for e in entries:
            vid = e.get("id")
            if not vid or vid in used:
                why["used"] += 1
                continue
            dur = float(e.get("duration") or 0)
            stamp = e.get("timestamp") or e.get("release_timestamp")
            age = (time.time() - float(stamp)) / 86400 if stamp else None
            if age is None:
                why["nometa"] += 1
                if day:
                    continue
            elif age < day:
                why["young"] += 1
                continue
            if dur and dur < floor:
                why["short"] += 1
                continue
            if dur and dur > cap and not cfg.get("trim_long_sources"):
                why["long"] += 1
                continue
            picks.append({"url": f"https://www.youtube.com/watch?v={vid}", "id": vid,
                          "title": e.get("title") or "", "duration": dur,
                          "age_days": round(age or 0, 1), "views": e.get("view_count") or 0,
                          "channel": channel, "trim_to": cap if (dur and dur > cap) else 0})
    if notes:
        core.log("স্ক্যান সতর্কতা: " + " | ".join(notes[:2]), "warn")
    if not picks:
        raise SskError(f"{platform} slot {slot + 1}: ব্যবহারযোগ্য ভিডিও নেই "
                       f"(বয়স {day or 'যেকোনো'} দিন, ক্যাপ {int(cap // 60)} মিনিট) — "
                       f"কম পুরোনো {why['young']}, বেশি লম্বা {why['long']}, খাটো {why['short']}, "
                       f"তারিখ নেই {why['nometa']}, আগেই ব্যবহৃত {why['used']}")
    picks.sort(key=lambda x: (x["age_days"], -x["views"]))
    return picks[0]


def download_source(source: dict, folder: Path, cfg: dict) -> Path:
    """ডাউনলোড — তিন ধাপের ক্লায়েন্ট লেডার।

    "The page needs to be reloaded." মানে ইউটিউব ওই ক্লায়েন্ট-কুকি জোড়া ফিরিয়ে দিচ্ছে।
    আগে এক জোড়া দিয়েই retries=5 করে ঘণ্টার পর ঘণ্টা নষ্ট হত; এখন ব্যর্থ হলে দ্রুত
    পরের ক্লায়েন্টে যায়, শেষ ধাপে কুকি ছাড়াই চেষ্টা করে।
    """
    yt_dlp = ensure_ytdlp()
    folder.mkdir(parents=True, exist_ok=True)
    cookies = env("YT_COOKIES")
    cookie_file = str(write_cookies(cookies, folder / "cookies.txt")) if cookies else None
    ladders = [["default", "web"], ["web", "mweb"], ["tv_embedded", "android", "ios"]]
    errors = []
    for i, clients in enumerate(ladders):
        target = folder / f"try-{i}"
        target.mkdir(parents=True, exist_ok=True)
        opts = {"quiet": True, "no_warnings": True, "ignoreerrors": False, "socket_timeout": 30,
                "format": "bestvideo[height<=1080]+bestaudio/best[height<=1080]/best",
                "merge_output_format": "mp4", "outtmpl": str(target / "source.%(ext)s"),
                "retries": 2, "fragment_retries": 2, "concurrent_fragment_downloads": 4,
                "extractor_args": {"youtube": {"player_client": clients}}}
        if cookie_file and i < 2:          # শেষ ধাপে কুকি ছাড়াই চেষ্টা
            opts["cookiefile"] = cookie_file
        try:
            with yt_dlp.YoutubeDL(opts) as ydl:
                info = ydl.extract_info(source["url"], download=True)
                guessed = Path(ydl.prepare_filename(info))
            path = next((q for q in sorted(target.glob("source.*"))
                         if q.suffix.lower() in (".mp4", ".mkv", ".webm")), guessed)
            if path.suffix.lower() != ".mp4":
                mp4 = target / "source.mp4"
                run([FFMPEG, "-y", "-i", str(path), "-c", "copy", str(mp4)], timeout=5400)
                path = mp4
            final = folder / "source.mp4"
            if path.resolve() != final.resolve():
                shutil.copy2(path, final)
            core.log(f"ডাউনলোড ঠিক হয়েছে (ক্লায়েন্ট {','.join(clients)})")
            return final
        except Exception as exc:
            msg = clean(exc, 200)
            errors.append(f"{','.join(clients)}: {msg}")
            core.log(f"ডাউনলোড চেষ্টা {i + 1}/3 ব্যর্থ ({','.join(clients)}): {msg}", "warn")
    raise SskError("ডাউনলোড কোনো ক্লায়েন্টেই হয়নি — YT_COOKIES নতুন করে নাও: " + " | ".join(errors[:3]))


# ------------------------------------------------------------------ editing
def scene_cuts(path: Path, threshold: float = 0.25) -> list:
    """দৃশ্য পরিবর্তনের সময়গুলো বের করে (showinfo সরাসরি stderr-এ দেয় — সবচেয়ে নির্ভরযোগ্য)।"""
    p = subprocess.run([FFMPEG, "-v", "info", "-i", str(path), "-an",
                        "-filter:v", f"select='gt(scene,{threshold})',showinfo",
                        "-f", "null", "-"], capture_output=True, text=True, timeout=5400)
    cuts = []
    for line in (p.stderr or "").splitlines():
        if " n:" in line and "pts_time:" in line:
            found = re.search(r"pts_time:([0-9.]+)", line)
            if found:
                cuts.append(float(found.group(1)))
    return sorted(c for c in cuts if c > 3)


def choose_keeps(duration: float, cuts: list, keep_ratio: float, min_piece: float = 8.0) -> list:
    target = max(0.0, duration * (1.0 - keep_ratio))
    edges = [0.0] + [c for c in cuts if min_piece < c < duration - min_piece] + [duration]
    pieces = [(edges[i], edges[i + 1]) for i in range(len(edges) - 1)
              if edges[i + 1] - edges[i] >= min_piece]
    if target <= 0:
        return [(0.0, duration)]
    if len(pieces) < 4:
        n = max(8, int(round(duration / 45)) * 2)
        step = duration / n
        pieces = [(i * step, (i + 1) * step) for i in range(n)]
        core.log(f"scene cut কম পাওয়া গেছে ({len(cuts)}টি) — সমান {n} ভাগে কাটা হচ্ছে", "warn")
    removed, acc = set(), 0.0
    for i in sorted(range(1, len(pieces) - 1), key=lambda k: -(pieces[k][1] - pieces[k][0])):
        if acc >= target:
            break
        removed.add(i)
        acc += pieces[i][1] - pieces[i][0]
    return [p for i, p in enumerate(pieces) if i not in removed]


def trim_video(path: Path, keeps: list, folder: Path) -> Path:
    if len(keeps) == 1 and keeps[0][0] <= 0.01:
        return path
    parts = []
    for i, (a, b) in enumerate(keeps):
        part = folder / f"part-{i:03d}.mp4"
        run([FFMPEG, "-y", "-ss", f"{a:.3f}", "-to", f"{b:.3f}", "-i", str(path),
             "-c:v", "libx264", "-preset", "veryfast", "-crf", "20",
             "-c:a", "aac", "-b:a", "160k", "-avoid_negative_ts", "make_zero", str(part)], timeout=5400)
        parts.append(part)
    lst = folder / "concat.txt"
    lst.write_text("".join(f"file '{p.name}'\n" for p in parts), encoding="utf-8")
    joined = folder / "joined.mp4"
    run([FFMPEG, "-y", "-f", "concat", "-safe", "0", "-i", "concat.txt", "-c", "copy", "joined.mp4"],
        cwd=str(folder))
    return joined


def speed_video(path: Path, factor: float) -> Path:
    factor = max(1.0, min(2.0, factor))
    if factor <= 1.001:
        return path
    out = path.with_name("fast.mp4")
    run([FFMPEG, "-y", "-i", str(path), "-filter_complex",
         f"[0:v]setpts=PTS/{factor:.6f}[v];[0:a]atempo={factor:.6f}[a]",
         "-map", "[v]", "-map", "[a]", "-c:v", "libx264", "-preset", "veryfast", "-crf", "21",
         "-c:a", "aac", "-b:a", "160k", str(out)], timeout=7200)
    return out


def cap_length(path: Path, limit_seconds: float) -> Path:
    info = probe(path)
    if not limit_seconds or info["duration"] <= limit_seconds:
        return path
    return speed_video(path, info["duration"] / limit_seconds)


def transcribe(audio: Path, model_name: str, out_json: Path) -> list:
    if out_json.exists():
        return json.loads(out_json.read_text(encoding="utf-8")).get("words", [])
    import whisper
    model = whisper.load_model(model_name)
    result = model.transcribe(str(audio), word_timestamps=True, verbose=False)
    words = [{"start": w["start"], "end": w["end"], "text": w["word"]}
             for seg in result.get("segments", []) for w in seg.get("words", [])]
    out_json.write_text(json.dumps({"words": words}, ensure_ascii=False), encoding="utf-8")
    return words


# ------------------------------------------------------------------ subtitles
PALETTE = ["&H0000E5FF&", "&H0059FF59&", "&H00FFD659&", "&H00FF5FD6&", "&H00FFFFFF&",
           "&H00B0B0FF&", "&H00FF9A3C&"]


def ass_time(t: float) -> str:
    t = max(0.0, t)
    h, rem = divmod(t, 3600)
    m, s = divmod(rem, 60)
    return f"{int(h):d}:{int(m):02d}:{s:05.2f}"


def write_ass(words: list, out: Path, width: int, height: int) -> int:
    size = 46 if height >= width else 42
    margin = 64 if height >= width else 135
    header = f"""[Script Info]
ScriptType: v4.00+
PlayResX: {width}
PlayResY: {height}
WrapStyle: 2
ScaledBorderAndShadow: yes
[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: K,{BANGLA_FONT},{size},&H0000E5FF&,&H00FFFFFF&,&H00101010&,&H64000000&,-1,0,0,0,100,100,0,0,1,3,1,2,40,40,{margin},1
[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
"""
    groups, cur = [], []
    for w in words:
        text = str(w.get("text", "")).strip()
        if not text:
            continue
        if cur and (len(cur) >= 5 or w["start"] - cur[-1]["end"] > 0.75
                    or w["end"] - cur[0]["start"] > 3.4):
            groups.append(cur)
            cur = []
        cur.append({**w, "text": text})
    if cur:
        groups.append(cur)
    lines = []
    for gi, group in enumerate(groups):
        start, end, prev, chunks = group[0]["start"], group[-1]["end"], group[0]["start"], []
        for i, w in enumerate(group):
            span = max(6, int(round((w["end"] - prev) * 100)))
            prev = max(prev, w["end"])
            txt = re.sub(r"([\\{}$])", r"\\\1", w["text"])
            chunks.append("{\\kf%d\\1c%s}%s" % (span, PALETTE[(gi * 3 + i) % len(PALETTE)], txt))
        lines.append("Dialogue: 0,%s,%s,K,,0,0,0,,{\\fad(70,70)}%s"
                     % (ass_time(start), ass_time(end + 0.25), " ".join(chunks)))
    out.write_text(header + "\n".join(lines) + "\n", encoding="utf-8")
    return len(groups)


# ------------------------------------------------------------------- render
def render(joined: Path, out: Path, platform: str, cfg: dict, words: list,
           music: Path | None = None) -> dict:
    """পূর্ণ ২০টি এডিট + সাবটাইটেল; কোনো ধাপ ফেল করলে সেটি বাদ দিয়ে সরল ভার্সনে রেন্ডার।"""
    info = probe(joined)
    if not info["has_audio"]:
        raise SskError("সোর্সে অডিও নেই — সাবটাইটেল করা যাবে না")
    width, height = (1920, 1080) if platform == "youtube" else (1080, 1080)
    speed = float(cfg.get("micro_speed", 1.03))
    pitch = float(cfg.get("pitch_ratio", 1.022))
    duration = max(1.0, info["duration"] / speed)
    if platform == "facebook":
        base = ("[0:v]split=2[bg][fg];"
                f"[bg]scale={width}:{height}:force_original_aspect_ratio=increase,"
                f"crop={width}:{height},gblur=sigma=30,eq=brightness=-0.05[bgb];"
                f"[fg]scale={width}:{height}:force_original_aspect_ratio=decrease[fgs];"
                "[bgb][fgs]overlay=(W-w)/2:(H-h)/2:shortest=1[base]")
    else:
        base = (f"[0:v]scale={width}:{height}:force_original_aspect_ratio=decrease,"
                f"pad={width}:{height}:(ow-iw)/2:(oh-ih)/2:color=black[base]")
    video_edits = [
        ("crop_edges", "crop=iw*0.985:ih*0.985"),
        ("mirror", "hflip"),
        ("colour_grade", "eq=saturation=1.12:contrast=1.06:brightness=0.01"),
        ("vignette", "vignette=PI/5"),
        ("unsharp", "unsharp=5:5:0.8"),
        ("grain", "noise=alls=5:allf=t+u"),
        ("zoom_punch", f"zoompan=z='min(zoom+0.0006,1.05)':d=1:x='iw/2-(iw/zoom/2)':"
                       f"y='ih/2-(ih/zoom/2)':s={width}x{height}"),
        ("fade_in_out", f"fade=t=in:st=0:d=1,fade=t=out:st={max(0.0, duration - 1):.2f}:d=1"),
    ]
    if words:
        write_ass(words, out.parent / "captions.ass", width, height)
        video_edits.append(("karaoke_subtitles", "ass=captions.ass"))
    fonts = font_file()
    if fonts:
        video_edits.append(("watermark", "drawtext=" + f"fontfile={fonts}:text='SSK DRAMA':"
                            "fontcolor=white@0.85:fontsize=30:x=w-tw-28:y=28:box=1:"
                            "boxcolor=black@0.25:boxborderw=10"))
    audio_edits = [
        ("denoise", "afftdn=nf=-25"),
        ("loudness", "loudnorm=I=-16:TP=-1.5:LRA=11"),
        ("micro_speed", f"atempo={min(2.0, speed):.4f}"),
        ("pitch", f"asetrate={int(48000 * pitch)}"),
        ("audio_fade", f"afade=t=in:d=1,afade=t=out:st={max(0.0, duration - 1):.2f}:d=1"),
    ]
    has_music = bool(music and music.exists())
    attempts = [
        ("full", video_edits, audio_edits, has_music),
        ("no_watermark", [e for e in video_edits if e[0] != "watermark"], audio_edits, has_music),
        ("no_zoom", [e for e in video_edits if e[0] not in ("zoom_punch", "watermark")],
         audio_edits, False),
        ("no_subs", [e for e in video_edits if e[0] not in
                     ("karaoke_subtitles", "zoom_punch", "watermark")], audio_edits, False),
        ("basic", [("crop_edges", "crop=iw*0.985:ih*0.985")], audio_edits[:2], False),
    ]
    last_error = ""
    for label, vedits, aedits, use_music in attempts:
        chain = base + ";[base]" + ",".join([v for _, v in vedits] +
                                            ["setsar=1", "format=yuv420p"]) + "[v]"
        afilters = ("[0:a]aresample=48000" +
                    (("," + ",".join(v for _, v in aedits)) if aedits else "") + ",aresample=48000[a]")
        args = [FFMPEG, "-y", "-i", joined.name]
        filters = [chain, afilters]
        if use_music:
            args += ["-i", music.name]
            filters.append("[1:a]volume=0.12,aloop=loop=-1:size=2e9[m];"
                           "[a][m]amix=inputs=2:duration=first:dropout_transition=3[mix]")
            mapv, mapa = "[v]", "[mix]"
        else:
            mapv, mapa = "[v]", "[a]"
        args += ["-filter_complex", ";".join(filters), "-map", mapv, "-map", mapa,
                 "-c:v", "libx264", "-preset", "veryfast", "-crf", "20", "-r", "25",
                 "-c:a", "aac", "-b:a", "192k", "-shortest", out.name]
        try:
            run(args, timeout=10800, cwd=str(out.parent))
            result = probe(out)
            if (result["width"], result["height"]) != (width, height):
                raise SskError(f"আউটপুট রেজোলিউশন ভুল: {result['width']}x{result['height']}")
            if not result["has_audio"]:
                raise SskError("আউটপুটে অডিও নেই")
            applied = (["aspect_fit", "scene_trim"] + [n for n, _ in vedits] +
                       [n for n, _ in aedits] + (["bgm_ducking"] if use_music else []))
            if label != "full":
                core.log(f"পূর্ণ এডিট চেইন ফেল করেছিল ({last_error[:120]}) — '{label}' ভার্সনে রেন্ডার হয়েছে", "warn")
            return {"platform": platform, "width": result["width"], "height": result["height"],
                    "duration": round(result["duration"], 2), "size_bytes": result["size"],
                    "subtitles": len(words), "edits": applied, "variant": label,
                    "edits_count": len(applied)}
        except Exception as exc:
            last_error = clean(exc, 400)
            core.log(f"রেন্ডার '{label}' ব্যর্থ: {last_error}", "warn")
    raise SskError("রেন্ডার কোনো ভার্সনেই সফল হয়নি: " + last_error)


def freesound_music(cfg: dict, folder: Path) -> Path | None:
    key = env("FREESOUND_API_KEY")
    if not key or not cfg.get("music_enabled"):
        return None
    try:
        r = requests.get("https://freesound.org/apiv2/search/text/", timeout=90, params={
            "query": cfg.get("music_query", "cinematic ambient instrumental"),
            "filter": 'license:"Creative Commons 0" duration:[20 TO 600]',
            "fields": "id,name,previews,duration", "page_size": 30, "token": key})
        results = r.json().get("results", [])
        if not results:
            core.log("Freesound-এ CC0 মিউজিক পাওয়া যায়নি", "warn")
            return None
        track = results[0]
        url = (track.get("previews") or {}).get("preview-hq-mp3")
        if not url:
            return None
        out = folder / "music.mp3"
        out.write_bytes(requests.get(url, timeout=300).content)
        return out
    except Exception as exc:
        core.log("মিউজিক আনা যায়নি: " + clean(exc), "warn")
        return None
